import type { ImageAsset } from "@/content/types";

/** Widths generated by scripts/optimize-images.mjs for each source image. */
export const IMAGE_WIDTHS = {
  wide: [640, 1024, 1600],
  portrait: [320, 640],
} as const;

interface PictureProps {
  image: ImageAsset;
  widths: readonly number[];
  sizes: string;
  priority?: boolean;
  className?: string;
}

/**
 * AVIF with WebP fallback, responsive srcset, explicit dimensions (no layout
 * shift) and lazy loading unless the image is above the fold.
 */
export function Picture({ image, widths, sizes, priority = false, className = "" }: PictureProps) {
  const srcSet = (format: string) =>
    widths.map((w) => `/images/${image.name}-${w}.${format} ${w}w`).join(", ");
  const largest = widths[widths.length - 1];

  return (
    <picture>
      <source type="image/avif" srcSet={srcSet("avif")} sizes={sizes} />
      <source type="image/webp" srcSet={srcSet("webp")} sizes={sizes} />
      <img
        src={`/images/${image.name}-${largest}.webp`}
        alt={image.alt}
        width={image.width}
        height={image.height}
        loading={priority ? "eager" : "lazy"}
        fetchPriority={priority ? "high" : "auto"}
        decoding="async"
        className={className}
      />
    </picture>
  );
}
